import json


def _reject_duplicate_keys(obj):
    """Recursively reject duplicate object keys at any nesting depth."""
    if isinstance(obj, dict):
        seen = set()
        for key in obj:
            if key in seen:
                raise ValueError(f"duplicate key: {key!r}")
            seen.add(key)
        for value in obj.values():
            _reject_duplicate_keys(value)
    elif isinstance(obj, list):
        for item in obj:
            _reject_duplicate_keys(item)


def parse_jsonl(text):
    """Parse newline-delimited JSON text into a list of decoded values.

    Whitespace-only lines are skipped. Malformed non-blank JSON lines raise
    ValueError. Unicode, CRLF line endings, and a final line without a
    trailing newline are handled. Duplicate object keys at any nesting depth
    raise ValueError.
    """
    result = []
    for line in text.splitlines():
        if not line.strip():
            continue
        value = json.loads(line)
        _reject_duplicate_keys(value)
        result.append(value)
    return result

